class TupleFunctionResultBindingTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	enum Constraint {
		UNBOUND,
		API,
		CONSTANT,
		INCOMING
	}

	@ParameterizedTest
	@CsvSource({ "UNBOUND,true", "UNBOUND,false", "API,true", "API,false", "CONSTANT,true", "CONSTANT,false",
			"INCOMING,true", "INCOMING,false" })
	void repeatedResultsConstrainEarlierColumns(Constraint constraint, boolean matching) {
		Value first = VF.createIRI("urn:first");
		Value second = matching ? first : VF.createIRI("urn:second");
		Var result = switch (constraint) {
		case UNBOUND, INCOMING -> Var.of("x");
		case API -> Var.of("x", first).withApiInputOrigin();
		case CONSTANT -> Var.of("x", first, true, true);
		};
		BindingSet incoming = EmptyBindingSet.getInstance();
		if (constraint == Constraint.INCOMING) {
			var bindings = new MapBindingSet();
			bindings.addBinding("x", first);
			incoming = bindings;
		}
		TupleFunction function = new TupleFunction() {
			@Override
			public String getURI() {
				return "urn:test:repeated-tuple-results";
			}

			@Override
			public CloseableIteration<? extends List<? extends Value>> evaluate(ValueFactory valueFactory,
					Value... args) {
				return new SingletonIteration<>(List.of(first, second));
			}
		};
		try (var rows = DefaultEvaluationStrategy.evaluate(function, List.of(result, result.clone()), incoming, VF)) {
			var collected = Iterations.asList(rows);
			assertEquals(matching ? 1 : 0, collected.size());
			if (matching) {
				assertEquals(first, collected.get(0).getValue("x"));
			}
		}
	}
}
